package ktanesolver.module.modded.regular.dominoes;
import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class DominoesSolverTest{@Test void subtractsAndOrdersDescendingFromUnlitIndicator(){var b=new BombEntity();b.setAaBatteryCount(3);b.setSerialNumber("AB1CD2");b.setIndicators(new HashMap<>(Map.of("CAR",false)));var r=new DominoesSolver().solve(new RoundEntity(),b,new ModuleEntity(),new DominoesInput(List.of(List.of(6,1),List.of(5,2),List.of(4,3),List.of(2,6))));var o=((SolveSuccess<DominoesOutput>)r).output();assertThat(o.operation()).isEqualTo("subtract");assertThat(o.values()).containsExactly(5,3,1,-4);assertThat(o.order()).containsExactly(1,2,3,4);}}
